{"command":"mkdir -p /tmp/proto && cat > /tmp/proto/main.go <<'EOF'
package main

import (
"fmt"
"go/ast"
"go/importer"
"go/parser"
"go/token"
"go/types"
)

type Fake struct{ pkgs map[string]*types.Package }
func (f *Fake) Import(path string)(*types.Package,error){
 if p,ok:=f.pkgs[path]; ok { return p,nil }
 // name based on path tail hack
 name:=path
 // create incomplete?
 p:=types.NewPackage(path,name)
 // add some? mark complete
 p.MarkComplete()
 f.pkgs[path]=p
 return p,nil
}
func main(){
 _=importer.Default
 src:=`package p
import ("fmt";"os")
func f(){ fmt:=struct{Println int}{}; _=fmt.Println; _=os.Args }
var _ = fmt.Println
`
 fset:=token.NewFileSet()
 file,err:=parser.ParseFile(fset,"a.go",src,parser.ParseComments)
 fmt.Println("parse",err)
 info:=&types.Info{Uses: map[*ast.Ident]types.Object{}, Defs: map[*ast.Ident]types.Object{}, Selections: map[*ast.SelectorExpr]*types.Selection{}}
 // fake importer with correct names for fmt/os but empty packages
 fk:=&Fake{pkgs:map[string]*types.Package{"fmt": types.NewPackage("fmt","fmt"),"os": types.NewPackage("os","os")}}
 for _,p:=range fk.pkgs{p.MarkComplete()}
 conf:=types.Config{Importer: fk, Error: func(err error){ fmt.Println("type err:",err)}, FakeImportC:true}
 pkg,err:=conf.Check("p",fset,[]*ast.File{file},info)
 fmt.Println("check",pkg,err)
 for id,obj:=range info.Uses {
   if obj!=nil { fmt.Printf("USE %s at %v -> %T %v pkg=%v\n",id.Name,fset.Position(id.Pos()),obj,obj,obj.Pkg()) } else { fmt.Printf("USE %s nil\n",id.Name)}
 }
 for id,obj:=range info.Defs { fmt.Printf("DEF %s at %v -> %T %v\n",id.Name,fset.Position(id.Pos()),obj,obj)}
}
EOF
cd /tmp/proto && go mod init proto >/dev/null 2>&1; go run ."}

