import os, shutil, subprocess, json
def write(p,c):
 os.makedirs(os.path.dirname(p),exist_ok=True); open(p,'w').write(c)
def setup(files):
 if os.path.exists("/tmp/projL"): shutil.rmtree("/tmp/projL")
 write("/tmp/projL/go.mod","module example.com/proj\n\ngo 1.21\n")
 for n,c in files.items(): write(f"/tmp/projL/{n}",c)
def golist(args):
 r=subprocess.run(["go","list","-e","-json","-test=true","-deps=false","--","."],cwd="/tmp/projL",capture_output=True,text=True)
 print("exit",r.returncode,"stderr",r.stderr)
 # multiple json objects parse via decoder
 dec=json.JSONDecoder(); s=r.stdout; idx=0; objs=[]
 while idx<len(s.strip()):
  o,end=dec.raw_decode(s,idx); objs.append(o); idx=end
  while idx<len(s) and s[idx].isspace(): idx+=1
 for o in objs:
  print({k:o.get(k) for k in ["ImportPath","Name","ForTest","GoFiles","TestGoFiles","XTestGoFiles","Imports","Error","DepsErrors","Incomplete","Standard"]})
fileslist=[
 ("buildtag sole missing", {"a.go":"//go:build never\n\npackage p\nimport (\"fmt\";\"example.com/missing/pkg\")\nvar _=fmt.Println\nvar _=pkg.X\n"}),
 ("windows", {"a_windows.go":"package p\nimport (\"fmt\";\"os\")\nvar _=fmt.Println\n","b.go":"package p\nvar X=1\n"}),
 ("other package", {"a.go":"package p\nimport (\"fmt\";\"os\")\nvar _=fmt.Println\n","b.go":"package other\nimport \"example.com/missing/pkg\"\nvar _=pkg.X\n"}),
 ("normal missing", {"a.go":"package p\nimport (\"fmt\";\"example.com/missing/pkg\")\nvar _=fmt.Println\nvar _=pkg.X\n"}),
 ("syntax other", {"a.go":"package p\nimport (\"fmt\";\"os\")\nvar _=fmt.Println\n","b.go":"package p\nfunc x( {\n"}),
 ("test missing non", {"a.go":"package p\nimport \"example.com/missing/pkg\"\nvar _=pkg.X\n","a_test.go":"package p\nimport (\"fmt\";\"os\")\nvar _=fmt.Println\n"}),
]
for name,files in fileslist:
 print("\n===",name); setup(files); golist([])
PY
"}

