cat > options.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"strings"
)

type importGroup string

const (
	groupStd     importGroup = "std"
	groupGeneral importGroup = "general"
	groupCompany importGroup = "company"
	groupProject importGroup = "project"
	groupBlanked importGroup = "blanked"
	groupDotted  importGroup = "dotted"
)

func defaultImportsOrder() []importGroup {
	return []importGroup{groupStd, groupGeneral, groupCompany, groupProject}
}

func parseImportsOrder(s string) ([]importGroup, error) {
	if s == "" {
		return defaultImportsOrder(), nil
	}
	parts := strings.Split(s, ",")
	out := make([]importGroup, 0, len(parts))
	seen := map[importGroup]bool{}
	for _, p := range parts {
		p = strings.TrimSpace(p)
		g := importGroup(p)
		switch g {
		case groupStd, groupGeneral, groupCompany, groupProject, groupBlanked, groupDotted:
		default:
			return nil, fmt.Errorf("unknown order group type: %q", p)
		}
		out = append(out, g)
		seen[g] = true
	}
	for _, required := range defaultImportsOrder() {
		if !seen[required] {
			return nil, errors.New(`use default at least 4 parameters to sort groups of your imports: "std,general,company,project"`)
		}
	}
	return out, nil
}

func parseCompanyPrefixes(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		// Keep empty entries: an empty prefix matches everything,
		// as it does in the observed tool.
		out = append(out, strings.TrimSpace(p))
	}
	return out
}

func parseExcludes(s string) []string {
	var out []string
	// These defaults are always present (as relative patterns).
	out = append(out, ".git", ".idea", ".vscode")
	if s == "" {
		return out
	}
	for _, p := range strings.Split(s, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		out = append(out, p)
	}
	return out
}

type options struct {
	rmUnused                bool
	setAlias                bool
	format                  bool
	applyToGenerated        bool
	separateNamed           bool
	listDiff                bool
	recursive               bool
	setExitStatus           bool
	useCache                bool
	output                  string
	projectNameFlag         string
	companyPrefixes         []string
	excludes                []string
	importsOrder            []importGroup
	companyPrefixesOriginal string
	excludesOriginal        string
}
EOF
gofmt -w options.go
"}

