{"command":"cat > gomod.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type modPos struct {
	line int
	col  int
}

type modToken struct {
	raw string
	pos modPos
}

type modLine struct {
	tokens []modToken
}

type modError struct {
	filename string
	pos      modPos
	msg      string
}

func (e *modError) Error() string {
	if e.pos.col > 1 {
		return fmt.Sprintf("%s:%d:%d: %s", e.filename, e.pos.line, e.pos.col, e.msg)
	}
	return fmt.Sprintf("%s:%d: %s", e.filename, e.pos.line, e.msg)
}

func tokenizeModFile(filename string, data []byte) ([]modLine, error) {
	text := string(data)
	lines := strings.Split(text, "\n")
	var out []modLine
	for li, line := range lines {
		// A trailing carriage return is part of the line ending for
		// tokenisation purposes.
		line = strings.TrimSuffix(line, "\r")
		var toks []modToken
		i := 0
		for i < len(line) {
			c := line[i]
			if c == ' ' || c == '\t' || c == '\r' {
				i++
				continue
			}
			if c == '/' && i+1 < len(line) && line[i+1] == '/' {
				break
			}
			if c == '/' && i+1 < len(line) && line[i+1] == '*' {
				return nil, &modError{filename, modPos{li + 1, i + 1}, "mod files must use // comments (not /* */ comments)"}
			}
			if c == '(' || c == ')' {
				toks = append(toks, modToken{line[i : i+1], modPos{li + 1, i + 1}})
				i++
				continue
			}
			if c == '"' {
				start := i
				i++
				closed := false
				for i < len(line) {
					if line[i] == '\\' {
						i += 2
						continue
					}
					if line[i] == '"' {
						i++
						closed = true
						break
					}
					i++
				}
				if !closed {
					return nil, &modError{filename, modPos{li + 1, len(line) + 1}, "unexpected newline in string"}
				}
				toks = append(toks, modToken{line[start:i], modPos{li + 1, start + 1}})
				continue
			}
			start := i
			for i < len(line) {
				c = line[i]
				if c == ' ' || c == '\t' || c == '\r' || c == '(' || c == ')' {
					break
				}
				if c == '/' && i+1 < len(line) && line[i+1] == '*' {
					return nil, &modError{filename, modPos{li + 1, i + 1}, "mod files must use // comments (not /* */ comments)"}
				}
				i++
			}
			// Progress is guaranteed except for the parenthesis
			// case, already handled above.
			toks = append(toks, modToken{line[start:i], modPos{li + 1, start + 1}})
		}
		if len(toks) > 0 {
			out = append(out, modLine{toks})
		}
	}
	return out, nil
}

func parseModString(filename string, tok modToken, stmtPos modPos) (string, error) {
	raw := tok.raw
	if !strings.ContainsAny(raw, "'\"`") {
		return raw, nil
	}
	if len(raw) >= 2 && raw[0] == '"' {
		s, err := strconv.Unquote(raw)
		if err != nil {
			// The reference parser reports this class of error
			// in this shortened form.
			return "", &modError{filename, stmtPos, "invalid quoted string: invalid syntax"}
		}
		return s, nil
	}
	return "", &modError{filename, stmtPos, "invalid quoted string: unquoted string cannot contain quote"}
}

func validGoDirectiveVersion(v string) bool {
	// Accept the normal 1.23 and 1.23.0 forms, plus release
	// candidates as written by Go toolchains.
	parts := strings.Split(v, ".")
	if len(parts) != 2 && len(parts) != 3 {
		return false
	}
	for i, p := range parts {
		if p == "" {
			return false
		}
		// Strip an rc/beta suffix from the minor version in the
		// two-component form.
		if i == 1 && len(parts) == 2 {
			for _, suf := range []string{"rc", "beta", "alpha"} {
				if idx := strings.Index(p, suf); idx > 0 {
					if !allDigits(p[idx+len(suf):]) {
						return false
					}
					p = p[:idx]
					break
				}
			}
		}
		if !allDigits(p) {
			return false
		}
	}
	return true
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

func parseGoModFile(filename string) (string, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return "", err
	}
	lines, err := tokenizeModFile(filename, data)
	if err != nil {
		return "", err
	}

	modulePath := ""
	moduleSeen := false

	applyStmt := func(verb string, args []modToken, pos modPos) error {
		parseArg := func(t modToken) (string, error) {
			return parseModString(filename, t, pos)
		}
		switch verb {
		case "module":
			if moduleSeen {
				return &modError{filename, pos, "repeated module statement"}
			}
			if len(args) != 1 {
				return &modError{filename, pos, "usage: module module/path"}
			}
			v, e := parseArg(args[0])
			if e != nil {
				return e
			}
			modulePath = v
			moduleSeen = true
			return nil
		case "go":
			if len(args) != 1 {
				return &modError{filename, pos, "go directive expects exactly one argument"}
			}
			v, e := parseArg(args[0])
			if e != nil {
				return e
			}
			if !validGoDirectiveVersion(v) {
				return &modError{filename, pos, fmt.Sprintf("invalid go version '%s': must match format 1.23.0", v)}
			}
			return nil
		case "toolchain":
			if len(args) != 1 {
				return &modError{filename, pos, "toolchain directive expects exactly one argument"}
			}
			v, e := parseArg(args[0])
			if e != nil {
				return e
			}
			if !strings.HasPrefix(v, "go") || !validGoDirectiveVersion(strings.TrimPrefix(v, "go")) {
				return &modError{filename, pos, fmt.Sprintf("invalid toolchain version '%s': must match format go1.23.0", v)}
			}
			return nil
		case "require":
			if len(args) != 2 {
				return &modError{filename, pos, "usage: require module/path v1.2.3"}
			}
			for _, a := range args {
				if _, e := parseArg(a); e != nil {
					return e
				}
			}
			return nil
		case "exclude":
			if len(args) != 2 {
				return &modError{filename, pos, "usage: exclude module/path v1.2.3"}
			}
			for _, a := range args {
				if _, e := parseArg(a); e != nil {
					return e
				}
			}
			return nil
		case "replace":
			arrow := -1
