			if len(args) == 0 {
				return &modError{filename, pos, "usage: retract v1.2.3"}
			}
			for _, a := range args {
				if _, e := parseArg(a); e != nil {
					return e
				}
			}
			return nil
		case "tool":
			if len(args) != 1 {
				return &modError{filename, pos, "usage: tool path"}
			}
			if _, e := parseArg(args[0]); e != nil {
				return e
			}
			return nil
		case "godebug":
