		}
	}

	for i := 0; i < len(lines); i++ {
		toks := lines[i].tokens
		verb := toks[0].raw
		pos := toks[0].pos
		if len(toks) == 2 && toks[1].raw == "(" {
			// Block form.
			closed := false
			for i++; i < len(lines); i++ {
				inner := lines[i].tokens
				if len(inner) == 1 && inner[0].raw == ")" {
					closed = true
					break
				}
				if err := applyStmt(verb, inner, inner[0].pos); err != nil {
