			}
			continue
		}
		if err := applyStmt(verb, toks[1:], pos); err != nil {
			return "", err
		}
	}
	if !moduleSeen {
		return "", errors.New("module is undefined")
	}
	return modulePath, nil
}

type projectFinder struct {
