				return &modError{filename, pos, "usage: replace module/path [v1.2.3] => other/module/path [v1.2.3]"}
			}
			var vals []string
			for i, a := range args {
				if i == arrow {
					continue
				}
				v, e := parseArg(a)
				if e != nil {
					return e
				}
				vals = append(vals, v)
			}
			if len(args)-arrow-1 == 1 {
				nw := vals[len(vals)-1]
				if !(strings.HasPrefix(nw, "/") || strings.HasPrefix(nw, ".")) {
					return &modError{filename, pos, "replacement module without version must be directory path (rooted or starting with . or ..)"}
				}
			}
			return nil
		case "retract":
			if len(args) == 0 {
				return &modError{filename, pos, "usage: retract v1.2.3"}
			}
			for _, a := range args {
				if _, e := parseArg(a); e != nil {
					return e
				}
			}
			return nil
		case "tool":
			if len(args) != 1 {
				return &modError{filename, pos, "usage: tool path"}
			}
			if _, e := parseArg(args[0]); e != nil {
				return e
			}
			return nil
		case "godebug":
			if len(args) == 0 {
				return &modError{filename, pos, "usage: godebug key=value"}
			}
			for _, a := range args {
				if _, e := parseArg(a); e != nil {
					return e
				}
			}
			return nil
		default:
			return &modError{filename, pos, fmt.Sprintf("unknown directive: %s", verb)}
		}
	}

	for i := 0; i < len(lines); i++ {
		toks := lines[i].tokens
		verb := toks[0].raw
		pos := toks[0].pos
		if len(toks) == 2 && toks[1].raw == "(" {
			// Block form.
			closed := false
			for i++; i < len(lines); i++ {
				inner := lines[i].tokens
				if len(inner) == 1 && inner[0].raw == ")" {
					closed = true
					break
				}
				if err := applyStmt(verb, inner, inner[0].pos); err != nil {
					return "", err
				}
			}
			if !closed {
				return "", &modError{filename, pos, "syntax error: unexpected EOF in block"}
			}
			continue
		}
		if err := applyStmt(verb, toks[1:], pos); err != nil {
			return "", err
		}
	}
	if !moduleSeen {
		return "", errors.New("module is undefined")
	}
	return modulePath, nil
}

type projectFinder struct {
	useCache bool
	cache    map[string]projectCacheEntry
}

type projectCacheEntry struct {
	name string
	err  error
}

func (f *projectFinder) parse(filename string) (string, error) {
	if f.useCache {
		if f.cache == nil {
			f.cache = map[string]projectCacheEntry{}
		}
		if e, ok := f.cache[filename]; ok {
			return e.name, e.err
		}
		name, err := parseGoModFile(filename)
		f.cache[filename] = projectCacheEntry{name, err}
		return name, err
	}
	return parseGoModFile(filename)
}

func (f *projectFinder) searchFrom(dir string) (string, bool, error) {
	for {
		candidate := filepath.Join(dir, "go.mod")
		if info, err := os.Stat(candidate); err == nil && info.Mode().IsRegular() {
			name, err := f.parse(candidate)
			return name, true, err
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false, nil
		}
		dir = parent
	}
}

func (f *projectFinder) find(path string, stdin bool) (string, error) {
	var start string
	if stdin {
		wd, err := os.Getwd()
		if err != nil {
			start = "."
		} else {
			start = wd
		}
	} else if info, err := os.Stat(path); err == nil && info.IsDir() {
		start = path
	} else {
		start = filepath.Dir(path)
	}
	if name, found, err := f.searchFrom(start); found {
		return name, err
	}
	return f.parse("go.mod")
}
