		if cg.Pos() >= f.Package {
			continue
		}
		for _, c := range cg.List {
			if generatedRe.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

func classifyImport(imp collectedImport, projectName string, o options) importGroup {
	hasBlanked := false
	hasDotted := false
	for _, g := range o.importsOrder {
		if g == groupBlanked {
			hasBlanked = true
		}
		if g == groupDotted {
			hasDotted = true
		}
	}
	p := imp.classPath
	if imp.name == "_" && hasBlanked {
		return groupBlanked
	}
	if imp.name == "." && hasDotted {
		return groupDotted
	}
	if stdPackages[p] {
		return groupStd
	}
	if projectName != "" && (p == projectName || strings.HasPrefix(p, projectName+"/")) {
		return groupProject
	}
	for _, prefix := range o.companyPrefixes {
		if strings.HasPrefix(p, prefix) {
			return groupCompany
		}
	}
