}

func sortImports(imps []collectedImport) {
	sort.SliceStable(imps, func(i, j int) bool {
		if imps[i].cleanPath != imps[j].cleanPath {
			return imps[i].cleanPath < imps[j].cleanPath
		}
		return imps[i].name < imps[j].name
	})
}

func dedupImports(imps []collectedImport) []collectedImport {
	var out []collectedImport
	index := map[string]int{}
	for _, imp := range imps {
		k := imp.name + "\x00" + imp.classPath
		if idx, ok := index[k]; ok {
			out[idx] = imp
			continue
		}
		index[k] = len(out)
		out = append(out, imp)
	}
	return out
}

type importDeclInfo struct {
	decl       *ast.GenDecl
	start      int // offset of the import keyword
	end        int // offset just after the declaration
	preservedC bool
	hasParen   bool
}

func renderImportLine(imp collectedImport) string {
	var b strings.Builder
	if imp.name != "" {
		b.WriteString(imp.name)
		b.WriteByte(' ')
	}
	b.WriteString(strconv.Quote(imp.cleanPath))
	if imp.comment != "" {
		b.WriteByte(' ')
		b.WriteString(imp.comment)
	}
	return b.String()
}

func buildImportDecl(groups [][]collectedImport, useParen bool) string {
	var all []collectedImport
	for _, g := range groups {
		all = append(all, g...)
	}
	if len(all) == 0 {
		return ""
	}
	if len(all) == 1 && !useParen {
		return "import " + renderImportLine(all[0])
	}
	var b strings.Builder
	b.WriteString("import (\n")
	for gi, g := range groups {
		if len(g) == 0 {
			continue
		}
		if gi > 0 {
			// Blank line between subgroups. (Whether a previous
			// subgroup was empty does not matter to gofmt.)
			b.WriteByte('\n')
		}
		for _, imp := range g {
			b.WriteByte('\t')
			b.WriteString(renderImportLine(imp))
			b.WriteByte('\n')
		}
	}
	b.WriteString(")")
	return b.String()
}

// fixGoSource is the core transformation. filename is used for parser
// positions/messages; loaderPath is the absolute file path used by the
// package loader (empty for stdin).
func fixGoSource(original []byte, filename string, loaderPath string, projectName string, o options, isStdin bool) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, original, parser.ParseComments)
	if err != nil {
		if len(original) == 0 {
			return nil, fmt.Errorf("file is empty and cannot be parsed as Go source, use -excludes flag to skip this file: %w", err)
		}
		return nil, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %w", err)
	}
	if !o.applyToGenerated && isGenerated(file) {
		return original, nil
	}
	// A file whose only import is "C" is returned untouched.
	if len(file.Imports) == 1 && classImportPath(file.Imports[0].Path.Value) == "C" {
		return original, nil
	}

	tokFile := fset.File(file.Pos())
	offset := func(p token.Pos) int { return tokFile.Offset(p) }

	var decls []importDeclInfo
	var mergedDeclIdx []int // indexes into decls
	var collected []collectedImport
	originalCollectedCount := 0
	hasBlankOrDot := false

	for _, d := range file.Decls {
		gd, ok := d.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		info := importDeclInfo{
			decl:     gd,
			start:    offset(gd.Pos()),
			end:      offset(gd.End()),
			hasParen: gd.Lparen != token.NoPos,
		}
		// A declaration consisting solely of an import of "C" is
		// preserved as-is (cgo preamble declarations in
		// particular).
		if len(gd.Specs) == 1 {
			if is, ok := gd.Specs[0].(*ast.ImportSpec); ok && classImportPath(is.Path.Value) == "C" {
				info.preservedC = true
			}
		}
		decls = append(decls, info)
		if info.preservedC {
			if is := gd.Specs[0].(*ast.ImportSpec); is.Name != nil && (is.Name.Name == "_" || is.Name.Name == ".") {
				hasBlankOrDot = true
			}
			continue
		}
		mergedDeclIdx = append(mergedDeclIdx, len(decls)-1)
		for _, spec := range gd.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			imp := collectedImport{
				classPath: classImportPath(is.Path.Value),
				cleanPath: cleanImportPath(is.Path.Value),
			}
			if is.Name != nil {
				imp.name = is.Name.Name
				if imp.name == "_" || imp.name == "." {
					hasBlankOrDot = true
				}
			}
			if is.Comment != nil {
				var parts []string
				for _, c := range is.Comment.List {
					parts = append(parts, c.Text)
				}
				imp.comment = strings.Join(parts, " ")
			}
			collected = append(collected, imp)
			originalCollectedCount++
		}
	}

	// Package loading, used by -rm-unused and -set-alias.
	if o.rmUnused || o.setAlias {
		loaded, err := loadPackageInfo(loaderPath, file, collected, isStdin)
		if err != nil {
			return nil, err
		}
		_ = loaded
		if o.rmUnused && !hasBlankOrDot {
			collected = filterUnused(collected, loaded, file, fset)
		}
		if o.setAlias {
			for i := range collected {
				if collected[i].name == "" {
					if actual, ok := loaded.namesByPath[collected[i].cleanPath]; ok {
						if actual != "" && actual != lastPathElement(collected[i].cleanPath) {
							collected[i].name = actual
						}
					}
				}
			}
		}
	}
	collected = dedupImports(collected)

	var result []byte
	if len(mergedDeclIdx) == 0 {
		formatted, err := format.Source(original)
		if err != nil {
			return nil, err
		}
		result = formatted
	} else if originalCollectedCount == 0 {
		// Only empty import declarations: delete them while
		// retaining any comments that were inside them.
		var buf bytes.Buffer
		last := 0
		declSet := map[int]bool{}
		for _, idx := range mergedDeclIdx {
			declSet[idx] = true
		}
		for idx, info := range decls {
			if !declSet[idx] {
				continue
			}
			buf.Write(original[last:info.start])
			// Preserve comments wholly inside the empty decl.
			var inner []string
			for _, cg := range file.Comments {
				if offset(cg.Pos()) >= info.start && offset(cg.End()) <= info.end {
					var parts []string
					for _, c := range cg.List {
						parts = append(parts, c.Text)
					}
					inner = append(inner, strings.Join(parts, "\n"))
				}
			}
			buf.WriteString(strings.Join(inner, "\n"))
			last = info.end
		}
		buf.Write(original[last:])
		formatted, err := format.Source(buf.Bytes())
		if err != nil {
			return nil, err
		}
		result = formatted
	} else {
		// Group and sort.
		byGroup := map[importGroup][]collectedImport{}
		for _, imp := range collected {
			g := classifyImport(imp, projectName, o)
			byGroup[g] = append(byGroup[g], imp)
		}
		for g := range byGroup {
			sortImports(byGroup[g])
		}
		var groups [][]collectedImport
		for _, g := range o.importsOrder {
			specs := byGroup[g]
			if len(specs) == 0 {
				continue
			}
			if o.separateNamed {
				var unnamed, named []collectedImport
				for _, s := range specs {
					if s.name == "" {
						unnamed = append(unnamed, s)
					} else {
						named = append(named, s)
					}
				}
				if len(unnamed) > 0 {
					groups = append(groups, unnamed)
				}
				if len(named) > 0 {
					groups = append(groups, named)
				}
			} else {
				groups = append(groups, specs)
			}
		}

		first := decls[mergedDeclIdx[0]]
		lastD := decls[mergedDeclIdx[len(mergedDeclIdx)-1]]
		built := buildImportDecl(groups, first.hasParen)
		if built == "" {
			// Everything was removed. If there is a preserved
			// "C" declaration, an empty import declaration is
			// left behind (matching the reference tool).
			for _, info := range decls {
				if info.preservedC {
					built = "import ()"
					break
				}
			}
		}

		var buf bytes.Buffer
		buf.Write(original[:first.start])
		buf.WriteString(built)
		// Preserve any standalone "C" declarations located
		// between the first and last merged declarations.
		for _, info := range decls {
			if !info.preservedC {
				continue
			}
			if info.start > first.start && info.start < lastD.end {
				buf.WriteByte('\n')
				s := info.start
				if info.decl.Doc != nil {
					s = offset(info.decl.Doc.Pos())
				}
				buf.Write(original[s:info.end])
			}
		}
		suffixStart := lastD.end
		// When several import declarations were merged and the
		// last one was unparenthesised, its trailing line
		// comment belongs to the (now embedded) import spec and
		// should not be repeated after the new block.
		if len(mergedDeclIdx) > 1 && !lastD.hasParen && len(lastD.decl.Specs) == 1 {
			if is, ok := lastD.decl.Specs[0].(*ast.ImportSpec); ok && is.Comment != nil {
				suffixStart = offset(is.Comment.End())
			}
		}
		buf.Write(original[suffixStart:])

		formatted, err := format.Source(buf.Bytes())
		if err != nil {
			return nil, err
		}
		result = formatted
	}

	if o.format {
		result = applyExtraFormat(result)
	}
	return result, nil
}

func lastPathElement(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[i+1:]
	}
	return p
}

// applyExtraFormat inserts a blank line between adjacent top-level
// declarations, unless the previous declaration has a trailing comment
// on its last line.
func applyExtraFormat(src []byte) []byte {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src
	}
	if len(file.Decls) < 2 {
		return src
	}
	lines := strings.Split(string(src), "\n")
	declStartLine := func(d ast.Decl) int {
		p := d.Pos()
		switch x := d.(type) {
		case *ast.GenDecl:
			if x.Doc != nil {
				p = x.Doc.Pos()
			}
		case *ast.FuncDecl:
			if x.Doc != nil {
				p = x.Doc.Pos()
			}
		}
		return fset.Position(p).Line
	}
	var insertBefore []int // 1-based line numbers
	for i := 1; i < len(file.Decls); i++ {
		prev := file.Decls[i-1]
		cur := file.Decls[i]
		prevEndLine := fset.Position(prev.End()).Line
		curStart := declStartLine(cur)
		if curStart != prevEndLine+1 {
			continue
		}
		// Trailing comment on the previous declaration's last
		// line suppresses the insertion.
		trailing := false
		curPos := cur.Pos()
		if gd, ok := cur.(*ast.GenDecl); ok && gd.Doc != nil {
			curPos = gd.Doc.Pos()
		}
		if fd, ok := cur.(*ast.FuncDecl); ok && fd.Doc != nil {
			curPos = fd.Doc.Pos()
		}
		for _, cg := range file.Comments {
			for _, c := range cg.List {
				if c.Pos() > prev.End() && c.Pos() < curPos && fset.Position(c.Pos()).Line == prevEndLine {
					trailing = true
				}
			}
		}
		if !trailing {
			insertBefore = append(insertBefore, curStart)
		}
	}
	if len(insertBefore) == 0 {
		return src
	}
	set := map[int]bool{}
	for _, l := range insertBefore {
		set[l] = true
	}
	var out []string
	for i, line := range lines {
		if set[i+1] {
			out = append(out, "")
		}
		out = append(out, line)
	}
	return []byte(strings.Join(out, "\n"))
}
