var generatedRe = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

type collectedImport struct {
	name      string
	classPath string // path literal with only double quotes trimmed
	cleanPath string // unquoted path
	comment   string
}

func cleanImportPath(raw string) string {
	if s, err := strconv.Unquote(raw); err == nil {
		return s
	}
	return strings.Trim(raw, "\"`")
}

func classImportPath(raw string) string {
	return strings.Trim(raw, "\"")
}

func isGenerated(f *ast.File) bool {
	for _, cg := range f.Comments {
		if cg.Pos() >= f.Package {
			continue
		}
		for _, c := range cg.List {
			if generatedRe.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

func classifyImport(imp collectedImport, projectName string, o options) importGroup {
	hasBlanked := false
	hasDotted := false
	for _, g := range o.importsOrder {
		if g == groupBlanked {
			hasBlanked = true
		}
		if g == groupDotted {
			hasDotted = true
		}
	}
	p := imp.classPath
	if imp.name == "_" && hasBlanked {
		return groupBlanked
	}
	if imp.name == "." && hasDotted {
		return groupDotted
	}
	if stdPackages[p] {
		return groupStd
	}
	if projectName != "" && (p == projectName || strings.HasPrefix(p, projectName+"/")) {
		return groupProject
	}
	for _, prefix := range o.companyPrefixes {
		if strings.HasPrefix(p, prefix) {
			return groupCompany
		}
	}
