func sortImports(imps []collectedImport) {
	sort.SliceStable(imps, func(i, j int) bool {
		if imps[i].cleanPath != imps[j].cleanPath {
			return imps[i].cleanPath < imps[j].cleanPath
		}
		return imps[i].name < imps[j].name
	})
}

func dedupImports(imps []collectedImport) []collectedImport {
	var out []collectedImport
	index := map[string]int{}
	for _, imp := range imps {
		k := imp.name + "\x00" + imp.classPath
		if idx, ok := index[k]; ok {
			out[idx] = imp
			continue
		}
		index[k] = len(out)
		out = append(out, imp)
