		}
		mergedDeclIdx = append(mergedDeclIdx, len(decls)-1)
		for _, spec := range gd.Specs {
			is, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			imp := collectedImport{
				classPath: classImportPath(is.Path.Value),
				cleanPath: cleanImportPath(is.Path.Value),
			}
			if is.Name != nil {
				imp.name = is.Name.Name
				if imp.name == "_" || imp.name == "." {
					hasBlankOrDot = true
				}
			}
			if is.Comment != nil {
				var parts []string
				for _, c := range is.Comment.List {
					parts = append(parts, c.Text)
				}
				imp.comment = strings.Join(parts, " ")
			}
			collected = append(collected, imp)
			originalCollectedCount++
		}
	}

	// Package loading, used by -rm-unused and -set-alias.
	if o.rmUnused || o.setAlias {
		loaded, err := loadPackageInfo(loaderPath, file, collected, isStdin)
		if err != nil {
			return nil, err
		}
		_ = loaded
		if o.rmUnused && !hasBlankOrDot {
