{"command":"cat > packages.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
)

type listError struct {
	ImportStack []string
	Pos         string
	Err         string
}

type listPackage struct {
	Dir            string
	ImportPath     string
	Name           string
	ForTest        string
	GoFiles        []string
	CgoFiles       []string
	IgnoredGoFiles []string
	TestGoFiles    []string
	XTestGoFiles   []string
	Imports        []string
	ImportMap      map[string]string
	Error          *listError
	DepsErrors     []*listError
	Incomplete     bool
	Standard       bool
}

type loadedInfo struct {
	namesByPath    map[string]string
	forceUnusedAll bool
}

var errPackageHasErrors = errors.New("package has an errors")

func runGoList(dir string, patterns ...string) ([]*listPackage, error) {
	args := []string{"list", "-e", "-json", "-test=true", "-deps=true", "-compiled=false", "-export=false", "--"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	cmd.Env = os.Environ()
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("err: %v: stderr: %s\n", err, stderr.String())
	}
	var pkgs []*listPackage
	dec := json.NewDecoder(&stdout)
	for dec.More() {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			return nil, err
		}
		pp := p
		pkgs = append(pkgs, &pp)
	}
	return pkgs, nil
}

func sameDir(a, b string) bool {
	if a == "" || b == "" {
		return false
	}
	ea, erra := filepath.EvalSymlinks(a)
	eb, errb := filepath.EvalSymlinks(b)
	if erra == nil && errb == nil {
		return ea == eb
	}
	aa, erra := filepath.Abs(a)
	ab, errb := filepath.Abs(b)
	if erra == nil && errb == nil {
		return aa == ab
	}
	return filepath.Clean(a) == filepath.Clean(b)
}

func containsString(xs []string, x string) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}

func printListError(e *listError) {
	pos := e.Pos
	if pos == "" {
		pos = "-"
	}
	fmt.Fprintf(os.Stderr, "%s: %s\n", pos, e.Err)
}

func findPkgByPath(pkgs []*listPackage, path string) int {
	best := -1
	for i, p := range pkgs {
		if p.ImportPath != path {
			continue
		}
		if best == -1 {
			best = i
			continue
		}
		// Prefer a named instance over an error placeholder when
		// duplicates (test variants) are present.
		if pkgs[best].Name == "" && p.Name != "" {
			best = i
		}
	}
	return best
}

// printGraphErrors prints package errors reachable from root, in
// dependency-first order, and returns how many were printed.
func printGraphErrors(pkgs []*listPackage, root int) int {
	visited := map[int]bool{}
	count := 0
	var visit func(int)
	visit = func(idx int) {
		if idx < 0 || visited[idx] {
			return
		}
		visited[idx] = true
		p := pkgs[idx]
		for _, imp := range p.Imports {
			resolved := imp
			if p.ImportMap != nil {
				if r, ok := p.ImportMap[imp]; ok && r != "" {
					resolved = r
				}
			}
			visit(findPkgByPath(pkgs, resolved))
		}
		if p.Error != nil {
			printListError(p.Error)
			count++
		}
	}
	visit(root)
	return count
}

func namesForRoot(pkgs []*listPackage, root int) map[string]string {
	out := map[string]string{}
	if root < 0 {
		return out
	}
	p := pkgs[root]
	for _, imp := range p.Imports {
		resolved := imp
		if p.ImportMap != nil {
			if r, ok := p.ImportMap[imp]; ok && r != "" {
				resolved = r
			}
		}
		idx := findPkgByPath(pkgs, resolved)
		if idx >= 0 && pkgs[idx].Name != "" {
			out[imp] = pkgs[idx].Name
		}
	}
	return out
}

func hasGoBuildLine(file *ast.File) bool {
	for _, cg := range file.Comments {
		if cg.Pos() >= file.Package {
			continue
		}
		for _, c := range cg.List {
			if strings.HasPrefix(c.Text, "//go:build") {
				return true
			}
		}
	}
	return false
}

func loadPackageInfo(loaderPath string, file *ast.File, specs []collectedImport, isStdin bool) (*loadedInfo, error) {
	if isStdin {
		fmt.Fprintln(os.Stderr, "-: no Go files in")
		return nil, errPackageHasErrors
	}
	dir := filepath.Dir(loaderPath)
	base := filepath.Base(loaderPath)

	pkgs, err := runGoList(dir, ".")
	if err != nil {
		return nil, err
	}

	isTest := strings.HasSuffix(base, "_test.go")
	isExternalTest := isTest && strings.HasSuffix(file.Name.Name, "_test")

	selected := -1
	var candIdx []int
	for i, p := range pkgs {
		if sameDir(p.Dir, dir) {
			candIdx = append(candIdx, i)
		}
	}
	// Selection passes, in decreasing specificity.
	for _, i := range candIdx {
		p := pkgs[i]
		if isExternalTest && containsString(p.XTestGoFiles, base) {
			selected = i
			break
		}
	}
	if selected < 0 {
		for _, i := range candIdx {
			p := pkgs[i]
			if isTest && containsString(p.TestGoFiles, base) && (p.ForTest != "" || strings.Contains(p.ImportPath, " [")) {
				selected = i
				break
			}
		}
	}
	if selected < 0 {
		for _, i := range candIdx {
			p := pkgs[i]
			if (containsString(p.GoFiles, base) || containsString(p.CgoFiles, base)) && p.ForTest == "" && !strings.HasSuffix(p.ImportPath, ".test") {
				selected = i
				break
			}
		}
	}
	if selected < 0 {
		for _, i := range candIdx {
			p := pkgs[i]
			if containsString(p.GoFiles, base) || containsString(p.CgoFiles, base) || containsString(p.TestGoFiles, base) || containsString(p.XTestGoFiles, base) {
				selected = i
				break
			}
		}
	}

	adHoc := false
	appendNoGoFiles := false
	normalCandWithFiles := false
	for _, i := range candIdx {
		if len(pkgs[i].GoFiles) > 0 || len(pkgs[i].CgoFiles) > 0 {
			normalCandWithFiles = true
		}
	}

	runAdHoc := func() bool {
		adPkgs, err := runGoList(dir, base)
		if err != nil {
			// Surface this via the package-error path.
			return false
		}
		for i, p := range adPkgs {
			if p.ImportPath == "command-line-arguments" && (containsString(p.GoFiles, base) || containsString(p.CgoFiles, base)) {
				pkgs = adPkgs
				selected = i
				adHoc = true
				return true
			}
		}
		return false
	}

	if selected < 0 && hasGoBuildLine(file) {
		if !normalCandWithFiles {
			appendNoGoFiles = true
		}
		runAdHoc()
	}
	if selected < 0 {
		// Fall back to a package in the same directory even if it
		// does not contain this file (windows/GOOS files,
		// underscore files, non-.go files, ...).
		for _, i := range candIdx {
			p := pkgs[i]
			if p.ForTest == "" && !strings.HasSuffix(p.ImportPath, ".test") && p.Name != "main" {
				selected = i
				break
			}
		}
		if selected < 0 && len(candIdx) > 0 {
			// Only use a bare candidate if it actually has Go
			// files; otherwise the ad-hoc form below matches
			// the reference behaviour better.
			for _, i := range candIdx {
				if len(pkgs[i].GoFiles) > 0 || len(pkgs[i].CgoFiles) > 0 || len(pkgs[i].TestGoFiles) > 0 {
					selected = i
					break
				}
			}
		}
	}
	if selected < 0 {
		if !runAdHoc() {
			fmt.Fprintln(os.Stderr, "-: no Go files in")
			return nil, errPackageHasErrors
		}
	}

	count := printGraphErrors(pkgs, selected)
	if count > 0 {
		if adHoc && normalCandWithFiles {
			// A build-constrained file handled ad hoc while a
			// normal package also exists: the reference tool
			// prints the loader errors but proceeds, treating
			// every import as unused.
			return &loadedInfo{namesByPath: namesForRoot(pkgs, selected), forceUnusedAll: true}, nil
		}
		if appendNoGoFiles {
			fmt.Fprintln(os.Stderr, "-: no Go files in")
		}
		return nil, errPackageHasErrors
	}
	return &loadedInfo{namesByPath: namesForRoot(pkgs, selected)}, nil
}

