		rootAbs = abs
		if info, err := os.Stat(abs); err == nil && info.IsDir() {
			isDir = true
		}
	}

	if isDir {
		if e.opts.listDiff {
			files, changedAny, err := e.walkDir(rootAbs, proj, effectiveRecursive, true)
			if err != nil {
				log.Fatalf("Failed to find unformatted files %s: %s", path, err)
			}
			for _, f := range files {
				fmt.Println(f)
			}
			if e.opts.setExitStatus && changedAny {
				os.Exit(1)
			}
			os.Exit(0)
		}
		if _, _, err := e.walkDir(rootAbs, proj, effectiveRecursive, false); err != nil {
			log.Fatalf("Failed to fix directory %s: %s", path, err)
		}
		return false
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}
	result, changed, err := e.fixSingleFile(absPath, proj)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err)
	}
	e.stickyChanged = e.stickyChanged || changed
	if e.opts.listDiff && e.stickyChanged {
		fmt.Println(absPath)
		if e.opts.output == "write" {
			writeFixed(absPath, result)
		}
		return changed
	}
	switch e.opts.output {
	case "stdout":
		_, _ = os.Stdout.Write(result)
	case "file", "write":
		if e.opts.listDiff {
			fmt.Println(absPath)
		}
		writeFixed(absPath, result)
	default:
		log.Fatalf("invalid output %q specified", e.opts.output)
	}
	return changed
}

func (e *executor) executeStdin(proj string) bool {
	original, err := io.ReadAll(os.Stdin)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err)
	}
	result, err := fixGoSource(original, "<standard-input>", "", proj, e.opts, true)
	if err != nil {
		log.Fatalf("Failed to fix file: %s", err)
	}
	changed := !bytes.Equal(original, result)
	e.stickyChanged = e.stickyChanged || changed
	if e.opts.listDiff && changed && e.opts.output != "write" {
		fmt.Println("<standard-input>")
		return changed
	}
	_, _ = os.Stdout.Write(result)
	return changed
}

func (e *executor) isExcluded(rootAbs string, path string) bool {
	for _, pattern := range e.opts.excludes {
		pat := pattern
		if !filepath.IsAbs(pat) {
			pat = filepath.Join(rootAbs, pat)
		}
		if matched, _ := filepath.Match(pat, path); matched {
			return true
		}
	}
	return false
}

func (e *executor) walkDir(rootAbs string, proj string, recursive bool, listMode bool) ([]string, bool, error) {
	var unformatted []string
	changedAny := false
	walkErr := filepath.Walk(rootAbs, func(path string, info os.FileInfo, err error) error {
		if info == nil {
			return nil
		}
		if e.isExcluded(rootAbs, path) {
			if info.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if info.IsDir() {
			if path != rootAbs && !recursive {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		result, changed, err := e.fixSingleFile(path, proj)
		if err != nil {
			return fmt.Errorf("failed to fix %s: %w", path, err)
		}
		if listMode {
			if changed {
				unformatted = append(unformatted, path)
				changedAny = true
			}
			return nil
		}
		writeFixed(path, result)
		return nil
	})
	if walkErr != nil {
		return nil, changedAny, fmt.Errorf("failed to walk dif: %w", walkErr)
	}
	return unformatted, changedAny, nil
}
