package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// externalDriverLoad implements enough of the go/packages external
// driver protocol (as used through GOPACKAGESDRIVER) for the
// NeedName|NeedImports load performed here.
// It returns handled=false when the driver reports NotHandled, in
// which case the caller should fall back to "go list".
func externalDriverLoad(dir string) (*loadedInfo, bool, error) {
	driver := os.Getenv("GOPACKAGESDRIVER")
	if driver == "" || driver == "off" {
		return nil, false, nil
	}
	req := map[string]any{
		"mode":        9, // NeedName | NeedImports
		"env":         os.Environ(),
		"build_flags": nil,
		"tests":       true,
		"overlay":     nil,
	}
	reqBytes, _ := json.Marshal(req)
	cmd := exec.Command(driver)
	cmd.Dir = dir
	cmd.Env = os.Environ()
	cmd.Stdin = bytes.NewReader(reqBytes)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, true, fmt.Errorf("%s: %v: %s\n", driver, err, stderr.String())
	}
	var raw map[string]any
	if err := json.Unmarshal(stdout.Bytes(), &raw); err != nil {
		return nil, true, err
	}
	if getBool(raw, "NotHandled") {
		return nil, false, nil
	}
	pkgsRaw := getSlice(raw, "Packages")
	type dpkg struct {
		id      string
		name    string
		pkgPath string
		imports map[string]string
		errs    []map[string]any
	}
	var dpkgs []*dpkg
	byID := map[string]*dpkg{}
	for _, item := range pkgsRaw {
		m, ok := item.(map[string]any)
		if !ok {
			continue
		}
		p := &dpkg{
			id:      getString(m, "ID"),
			name:    getString(m, "Name"),
			pkgPath: getString(m, "PkgPath"),
			imports: map[string]string{},
		}
		if im, ok := lookupCI(m, "Imports").(map[string]any); ok {
			for k, v := range im {
				if s, ok := v.(string); ok {
					p.imports[k] = s
				}
			}
		}
		for _, e := range getSlice(m, "Errors") {
			if em, ok := e.(map[string]any); ok {
				p.errs = append(p.errs, em)
			}
		}
		dpkgs = append(dpkgs, p)
		if p.id != "" {
			byID[p.id] = p
		}
	}
	var roots []*dpkg
	for _, r := range getSlice(raw, "Roots") {
		if s, ok := r.(string); ok {
			if p, ok := byID[s]; ok {
				roots = append(roots, p)
			}
		}
	}
	if len(roots) == 0 {
		roots = dpkgs
	}
	// Print errors, dependencies first.
	visited := map[*dpkg]bool{}
	errCount := 0
	var visit func(*dpkg)
	visit = func(p *dpkg) {
		if p == nil || visited[p] {
			return
		}
		visited[p] = true
		// Deterministic order: imports are visited in the order
		// given by sorted paths.
		var paths []string
		for path := range p.imports {
			paths = append(paths, path)
		}
		sortStrings(paths)
		for _, path := range paths {
			visit(byID[p.imports[path]])
		}
		for _, e := range p.errs {
			pos := getString(e, "Pos")
			if pos == "" {
				pos = "-"
			}
			fmt.Fprintf(os.Stderr, "%s: %s\n", pos, getString(e, "Msg"))
			errCount++
		}
	}
	for _, r := range roots {
		visit(r)
	}
	if errCount > 0 {
		return nil, true, errPackageHasErrors
	}
	names := map[string]string{}
	for _, r := range roots {
		for path, id := range r.imports {
			if dep, ok := byID[id]; ok && dep.name != "" {
				names[path] = dep.name
			}
		}
	}
	return &loadedInfo{namesByPath: names}, true, nil
}

func sortStrings(xs []string) {
	for i := 1; i < len(xs); i++ {
		for j := i; j > 0 && xs[j] < xs[j-1]; j-- {
			xs[j], xs[j-1] = xs[j-1], xs[j]
		}
	}
}

func lookupCI(m map[string]any, key string) any {
	if v, ok := m[key]; ok {
		return v
	}
	lk := strings.ToLower(key)
	for k, v := range m {
		if strings.ToLower(k) == lk {
			return v
		}
	}
	return nil
}

func getString(m map[string]any, key string) string {
	if s, ok := lookupCI(m, key).(string); ok {
		return s
	}
	return ""
}

func getBool(m map[string]any, key string) bool {
	if b, ok := lookupCI(m, key).(bool); ok {
		return b
	}
	return false
}

func getSlice(m map[string]any, key string) []any {
	if s, ok := lookupCI(m, key).([]any); ok {
		return s
	}
	return nil
}
