			if em, ok := e.(map[string]any); ok {
				p.errs = append(p.errs, em)
			}
		}
		dpkgs = append(dpkgs, p)
		if p.id != "" {
			byID[p.id] = p
		}
	}
	var roots []*dpkg
	for _, r := range getSlice(raw, "Roots") {
		if s, ok := r.(string); ok {
			if p, ok := byID[s]; ok {
				roots = append(roots, p)
			}
		}
	}
	if len(roots) == 0 {
		roots = dpkgs
	}
	// Print errors, dependencies first.
	visited := map[*dpkg]bool{}
	errCount := 0
	var visit func(*dpkg)
	visit = func(p *dpkg) {
		if p == nil || visited[p] {
			return
		}
		visited[p] = true
		// Deterministic order: imports are visited in the order
		// given by sorted paths.
		var paths []string
		for path := range p.imports {
			paths = append(paths, path)
		}
		sortStrings(paths)
		for _, path := range paths {
			visit(byID[p.imports[path]])
		}
		for _, e := range p.errs {
			pos := getString(e, "Pos")
			if pos == "" {
				pos = "-"
			}
			fmt.Fprintf(os.Stderr, "%s: %s\n", pos, getString(e, "Msg"))
			errCount++
		}
	}
	for _, r := range roots {
		visit(r)
	}
	if errCount > 0 {
		return nil, true, errPackageHasErrors
	}
	names := map[string]string{}
	for _, r := range roots {
		for path, id := range r.imports {
			if dep, ok := byID[id]; ok && dep.name != "" {
				names[path] = dep.name
			}
		}
	}
	return &loadedInfo{namesByPath: names}, true, nil
}

func sortStrings(xs []string) {
	for i := 1; i < len(xs); i++ {
		for j := i; j > 0 && xs[j] < xs[j-1]; j-- {
			xs[j], xs[j-1] = xs[j-1], xs[j]
		}
	}
}

func lookupCI(m map[string]any, key string) any {
	if v, ok := m[key]; ok {
		return v
	}
	lk := strings.ToLower(key)
	for k, v := range m {
		if strings.ToLower(k) == lk {
			return v
		}
	}
	return nil
}

func getString(m map[string]any, key string) string {
	if s, ok := lookupCI(m, key).(string); ok {
		return s
	}
	return ""
}

func getBool(m map[string]any, key string) bool {
	if b, ok := lookupCI(m, key).(bool); ok {
		return b
	}
	return false
}

func getSlice(m map[string]any, key string) []any {
	if s, ok := lookupCI(m, key).([]any); ok {
		return s
	}
	return nil
}
