    // Build metadata.
    if i := strings.Index(rest, "+"); i >= 0 {
        build := rest[i+1:]
        if build == "" { return false }
        for _, id := range strings.Split(build, ".") {
            if id == "" { return false }
            for _, r := range id { if !(r=='-' || ('0'<=r && r<='9') || ('a'<=r && r<='z') || ('A'<=r && r<='Z')) { return false } }
        }
        rest = rest[:i]
    }
    if i := strings.Index(rest, "-"); i >= 0 {
        pre := rest[i+1:]
        if pre == "" { return false }
        for _, id := range strings.Split(pre, ".") {
            if id == "" { return false }
            numeric := true
            for _, r := range id {
                if !(r=='-' || ('0'<=r && r<='9') || ('a'<=r && r<='z') || ('A'<=r && r<='Z')) { return false }
                if r<'0' || r>'9' { numeric=false }
            }
            if numeric && len(id)>1 && id[0]=='0' { return false }
        }
