import sys;sys.path.insert(0,'/tmp');from difftest import compare
def D(c):return {'go.mod':'module x\n','a.go':c}
cases={
'line directive between':'package p\nvar X=1\n//line other:20\nvar Y=2\nvar Z=3\n',
'comment block after prev same line doc next':'package p\nvar X=1 /*x*/\n// Y doc\nvar Y=2\n',
'comment multi after prev starts same line':'package p\nvar X=1 /*x\ny*/\nvar Y=2\n',
'comment before first in group':'package p\nvar (X=1\nY=2)\nvar Z=3\n',
'comment detached between format':'package p\nvar X=1\n// detached\n\nvar Y=2\nvar Z=3\n',
'comment doc with blank internal':'package p\n// X\n//\n// more\nvar X=1\n// Y\nvar Y=2\n',
}
for n,c in cases.items():compare(n,D(c),['-format','-output','stdout','@BASE@/a.go'])
PY
"}

